from ledgerline import Client

client = Client(api_key="LL_API_KEY", timeout=30)
token = None
while True:
    page = client.query("entries", filter={"currency": "usd"}, limit=200, page_token=token)
    for e in page.items:
        print(e["id"])
    token = page.next_page_token
    if token is None:
        break

